using UnityEngine;

[RequireComponent(typeof(SpriteRenderer))]
public class WaterBodyGradient : MonoBehaviour
{
    public Color topColor = Color.white;
    public Color midColor = Color.white;
    public Color bottomColor = Color.white;

    private SpriteRenderer _spriteRenderer;

    private void Awake()
    {
        _spriteRenderer = GetComponent<SpriteRenderer>();
    }

    private void Start()
    {
        Texture2D texture = new Texture2D(1, 3, TextureFormat.RGBA32, false);
        texture.filterMode = FilterMode.Bilinear;
        texture.wrapMode = TextureWrapMode.Clamp;

        texture.SetPixel(0, 2, topColor);
        texture.SetPixel(0, 1, midColor);
        texture.SetPixel(0, 0, bottomColor);
        texture.Apply();

        Sprite sprite = Sprite.Create(
            texture,
            new Rect(0f, 0f, texture.width, texture.height),
            new Vector2(0.5f, 0.5f),
            1f);

        _spriteRenderer.sprite = sprite;
    }
}

using UnityEngine;

[RequireComponent(typeof(SpriteRenderer))]
public class WaterBodyGradient : MonoBehaviour
{
    public Color topColor = Color.white;
    public Color midColor = Color.white;
    public Color bottomColor = Color.white;

    private SpriteRenderer _spriteRenderer;

    private void Awake()
    {
        _spriteRenderer = GetComponent<SpriteRenderer>();
    }

    private void Start()
    {
        int textureHeight = 64;
        if (_spriteRenderer.sprite != null)
        {
            float pixelsPerUnit = _spriteRenderer.sprite.pixelsPerUnit;
            float spritePixelHeight = _spriteRenderer.sprite.rect.height;
            float scaleY = Mathf.Abs(_spriteRenderer.transform.lossyScale.y);
            textureHeight = Mathf.Max(2, Mathf.RoundToInt(spritePixelHeight * scaleY));
        }

        int maxTextureSize = SystemInfo.maxTextureSize;
        textureHeight = Mathf.Clamp(textureHeight, 2, maxTextureSize);

        Texture2D texture = new Texture2D(1, textureHeight, TextureFormat.RGBA32, false);
        texture.filterMode = FilterMode.Bilinear;
        texture.wrapMode = TextureWrapMode.Clamp;

        for (int y = 0; y < textureHeight; y++)
        {
            float t = textureHeight == 1 ? 0f : (float)y / (textureHeight - 1);
            Color color;
            if (t < 0.5f)
            {
                float segmentT = t * 2f;
                color = Color.Lerp(bottomColor, midColor, segmentT);
            }
            else
            {
                float segmentT = (t - 0.5f) * 2f;
                color = Color.Lerp(midColor, topColor, segmentT);
            }

            texture.SetPixel(0, y, color);
        }

        texture.Apply();

        Sprite sprite = Sprite.Create(
            texture,
            new Rect(0f, 0f, texture.width, texture.height),
            new Vector2(0.5f, 0.5f),
            1f);

        _spriteRenderer.sprite = sprite;
    }
}
